import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"消息通道模式（Message Channel）","description":"","frontmatter":{},"headers":[],"relativePath":"integration/message-channel.md","filePath":"integration/message-channel.md","lastUpdated":0}`),a={name:`integration/message-channel.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="消息通道模式-message-channel" tabindex="-1">消息通道模式（Message Channel） <a class="header-anchor" href="#消息通道模式-message-channel" aria-label="Permalink to “消息通道模式（Message Channel）”">​</a></h1><p>消息通道是发送方与接收方之间的抽象管道：发送方把消息写进通道，接收方从通道读，双方不持有对方的地址，也不要求对方在线。它出自 Hohpe 与 Woolf 的《Enterprise Integration Patterns》[S10]，要解决的问题是点对点调用把三样东西绑死——位置（必须知道对方地址）、可用性（对方不在线就失败）、速率（对方处理不动，调用方跟着堵）。通道把三样一起解开：消息先落在通道里，接收方按自己的节奏消费。</p><h2 id="两种通道" tabindex="-1">两种通道 <a class="header-anchor" href="#两种通道" aria-label="Permalink to “两种通道”">​</a></h2><ul><li><strong>点对点通道（Point-to-Point Channel）</strong>：一条消息恰好被一个消费者处理，队列语义。适合&quot;这件事要有人做，做一次就够&quot;——下单扣库存、发邮件。</li><li><strong>发布订阅通道（Publish-Subscribe Channel）</strong>：一条消息投递给所有订阅者，见<a href="/hello-design-patterns/integration/publish-subscribe">发布订阅</a>。适合&quot;这件事发生了，谁关心谁订阅&quot;——订单已创建，积分、通知、报表各自消费。</li></ul><p>通道解耦不免费：一致性从&quot;同事务&quot;退化为&quot;最终一致&quot;，重复投递与乱序要显式处理（幂等消费、序号字段）。同步调用改异步消息之前，先确认业务容忍这个差别。</p><h2 id="适用与不适用" tabindex="-1">适用与不适用 <a class="header-anchor" href="#适用与不适用" aria-label="Permalink to “适用与不适用”">​</a></h2><p>适用于：发送方与接收方需要独立部署与扩缩容；流量有尖峰需要削峰；一个动作触发多个下游。</p><p>不适用：</p><ol><li>调用方需要立刻拿到结果：请求-响应语义用消息要做关联 ID 异步等待，复杂度远超一次 RPC。</li><li>强一致写操作：库存扣减这类不容许中间态的操作，最终一致是错误答案。</li><li>进程内协作：同一进程里传数据直接传引用，<a href="/hello-design-patterns/concurrency/producer-consumer">生产者-消费者</a>就是进程内的通道同构。</li></ol><h2 id="与其他模式的关系" tabindex="-1">与其他模式的关系 <a class="header-anchor" href="#与其他模式的关系" aria-label="Permalink to “与其他模式的关系”">​</a></h2><ul><li>与<a href="/hello-design-patterns/concurrency/producer-consumer">生产者-消费者</a>：同一语义在进程内与跨进程的两个实现——队列换成中间件，线程换成服务。</li><li>与<a href="/hello-design-patterns/integration/publish-subscribe">发布订阅</a>：通道的第二种形态，一条消息对多个订阅者。</li><li>与<a href="/hello-design-patterns/integration/message-router">消息路由</a>、<a href="/hello-design-patterns/integration/message-translator">消息转换</a>：通道是地基，路由与转换是通道上的加工组件。</li></ul><h2 id="关键参数" tabindex="-1">关键参数 <a class="header-anchor" href="#关键参数" aria-label="Permalink to “关键参数”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>取值依据</th><th>设错的后果</th></tr></thead><tbody><tr><td>通道容量 / 分区数</td><td>消费速率 × 可容忍的积压时长</td><td>太小削峰失效，太大积压不可见</td></tr><tr><td>投递保证</td><td>at-least-once 为默认，消费端配幂等</td><td>当成 exactly-once 用，重复消费写脏数据</td></tr><tr><td>死信出口</td><td>必配：消费失败 N 次后转入死信通道</td><td>一条毒消息堵死整条通道</td></tr></tbody></table><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><p>Go 实现：带缓冲 channel 就是一个进程内的点对点通道——多个 worker 消费同一条队列，一条消息恰好被一个 worker 处理。</p><div class="language-go line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">go</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#F97583;">package</span><span style="color:#B392F0;"> channel</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">import</span><span style="color:#9ECBFF;"> &quot;</span><span style="color:#B392F0;">fmt</span><span style="color:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">type</span><span style="color:#B392F0;"> Order</span><span style="color:#F97583;"> struct</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">	ID </span><span style="color:#F97583;">string</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#818e99;">// Start 起一条点对点通道：容量即削峰水位，一条消息恰好被一个 worker 消费</span></span>
<span class="line"><span style="color:#F97583;">func</span><span style="color:#B392F0;"> Start</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">workers</span><span style="color:#F97583;"> int</span><span style="color:#E1E4E8;">) </span><span style="color:#F97583;">chan&lt;-</span><span style="color:#B392F0;"> Order</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">	ch </span><span style="color:#F97583;">:=</span><span style="color:#B392F0;"> make</span><span style="color:#E1E4E8;">(</span><span style="color:#F97583;">chan</span><span style="color:#B392F0;"> Order</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">256</span><span style="color:#E1E4E8;">)</span></span>
<span class="line"><span style="color:#F97583;">	for</span><span style="color:#E1E4E8;"> i </span><span style="color:#F97583;">:=</span><span style="color:#79B8FF;"> 0</span><span style="color:#E1E4E8;">; i </span><span style="color:#F97583;">&lt;</span><span style="color:#E1E4E8;"> workers; i</span><span style="color:#F97583;">++</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#F97583;">		go</span><span style="color:#F97583;"> func</span><span style="color:#E1E4E8;">() {</span></span>
<span class="line"><span style="color:#F97583;">			for</span><span style="color:#E1E4E8;"> o </span><span style="color:#F97583;">:=</span><span style="color:#F97583;"> range</span><span style="color:#E1E4E8;"> ch {</span></span>
<span class="line"><span style="color:#B392F0;">				process</span><span style="color:#E1E4E8;">(o) </span><span style="color:#818e99;">// 消费失败要转入死信通道，不能丢</span></span>
<span class="line"><span style="color:#E1E4E8;">			}</span></span>
<span class="line"><span style="color:#E1E4E8;">		}()</span></span>
<span class="line"><span style="color:#E1E4E8;">	}</span></span>
<span class="line"><span style="color:#F97583;">	return</span><span style="color:#E1E4E8;"> ch</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">func</span><span style="color:#B392F0;"> process</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">o</span><span style="color:#B392F0;"> Order</span><span style="color:#E1E4E8;">) {</span></span>
<span class="line"><span style="color:#E1E4E8;">	fmt.</span><span style="color:#B392F0;">Println</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;processing&quot;</span><span style="color:#E1E4E8;">, o.ID)</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><p>跨进程时通道由消息中间件承担：RabbitMQ 的队列、Kafka 的 topic 分区、JMS 的 Queue，语义同型——发方 <code>publish</code>，收方 <code>consume</code>，容量与持久化由中间件配置。</p><p>Java 侧按框架对号入座：JMS 的 <code>Queue</code> 是点对点通道、<code>Topic</code> 是发布订阅通道；Spring Integration 的 <code>MessageChannel</code> 分 <code>DirectChannel</code>（同进程同步分发）与 <code>QueueChannel</code>（缓冲异步）；Kafka 的 topic 按 partition 顺序投递。</p><h2 id="接入时的三件小事" tabindex="-1">接入时的三件小事 <a class="header-anchor" href="#接入时的三件小事" aria-label="Permalink to “接入时的三件小事”">​</a></h2><ol><li><strong>消息带版本</strong>：消息体要跨进程长期飞，字段演进从第一天就打版本号，转换交给<a href="/hello-design-patterns/integration/message-translator">消息转换</a>。</li><li><strong>死信出口必配</strong>：消费失败重试几次后转死信通道，人工或定时任务兜底，否则一条毒消息堵死整条通道。</li><li><strong>积压要可见</strong>：通道容量、消费滞后（lag）是第一监控指标，积压曲线比用户投诉早半天。</li></ol><h2 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to “相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/integration/publish-subscribe">发布订阅</a>：通道的第二种形态。</li><li><a href="/hello-design-patterns/integration/message-router">消息路由</a>、<a href="/hello-design-patterns/integration/message-translator">消息转换</a>：通道上的加工组件。</li><li><a href="/hello-design-patterns/concurrency/producer-consumer">生产者-消费者模式</a>：进程内同构。</li><li><a href="/hello-design-patterns/integration/overview">集成模式导读</a>：本区口径。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S10] Gregor Hohpe、Bobby Woolf，《Enterprise Integration Patterns》，Addison-Wesley，2002。消息通道的原始出处。</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};